const apiKeyAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"

// newAPIKeyToken returns "tly_" followed by 40 random characters from apiKeyAlphabet. Bytes from 248 up are skipped, so
// that every character is equally likely (248 is the largest multiple of 62 below 256).
func newAPIKeyToken() string {
	const n = 40
	out := make([]byte, 0, n)
	buf := make([]byte, n)
	for len(out) < n {
		if _, err := rand.Read(buf); err != nil {
			panic(err) // crypto/rand does not fail on supported platforms
		}
		for _, b := range buf {
			if b < 248 && len(out) < n {
				out = append(out, apiKeyAlphabet[int(b)%len(apiKeyAlphabet)])
			}
		}
	}
	return "tly_" + string(out)
}

