func TestAPIKeyTokensAreRandomAndWellFormed(t *testing.T) {
	seen := map[string]bool{}
	for i := 0; i < 500; i++ {
		tok := newAPIKeyToken()
		if !apiKeyFormat.MatchString(tok) || seen[tok] {
			t.Fatalf("token %q is malformed or repeated", tok)
		}
		seen[tok] = true
	}
}

func TestAPIKeysAreStoredHashed(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleOwner, t0)
	k, err := s.CreateAPIKey(o.ID, u.ID, "k", t0)
	if err != nil || k.Token == "" {
		t.Fatalf("create = %+v, %v", k, err)
	}
	sum := sha256.Sum256([]byte(k.Token))
	listed := s.APIKeys(o.ID)
	if len(listed) != 1 || listed[0].Token != "" || listed[0].Hash != hex.EncodeToString(sum[:]) || listed[0].Last4 != k.Token[len(k.Token)-4:] {
		t.Fatalf("stored key = %+v", listed)
	}
	if got, ok := s.APIKey(o.ID, k.ID); !ok || got.Token != "" {
		t.Fatalf("APIKey = %+v %v", got, ok)
	}
	b, err := json.Marshal(s.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(b), k.Token) {
		t.Fatal("the exported state holds the plain-text token")
	}
}

func TestTouchAPIKeyIsThrottled(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "k", t0)
	lastUsed := func() time.Time {
		got, _ := s.APIKey(o.ID, k.ID)
		if got.LastUsedAt == nil {
			t.Fatal("LastUsedAt is nil")
		}
		return *got.LastUsedAt
	}
	s.TouchAPIKey(k.ID, t0)
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if got := lastUsed(); !got.Equal(t0) {
		t.Fatalf("a use 59 seconds later was recorded: %v", got)
	}
	s.TouchAPIKey(k.ID, t0.Add(60*time.Second))
	if got := lastUsed(); !got.Equal(t0.Add(60 * time.Second)) {
		t.Fatalf("a use 60 seconds later was not recorded: %v", got)
	}
}

